                    val failure = if (error is java.io.IOException) Wire.ioFailure(error) else error
                    val wait = if (failure is ApiTransportException && retryAllowed && attempt < options.maxRetries) Wire.retryWait(attempt, null, retryClock() - started, retryRandom(), retryClock(), options) else null
                    if (wait == null) throw failure
                    trace.retry(null, failure, wait)
                    retrySleep(wait)
                    attempt += 1
                    continue
                }
                trace.status = response.statusCode
                if (response.statusCode in 200..299) {
                    val decoded = if (response.value.isBlank()) null else Json.parse(response.value)
                    val result = ApiResult(decoder(decoded), response.statusCode, response.headers)
                    trace.success(response.statusCode)
                    return result
                }
                val retryable = Wire.shouldRetry(response.statusCode, response.headers)
                val wait = if (retryable && retryAllowed && attempt < options.maxRetries) Wire.retryWait(attempt, response.headers, retryClock() - started, retryRandom(), retryClock(), options) else null
                if (wait == null) throw ApiHttpException.of(response.statusCode, response.headers, response.value, errors, operationId, attempt + 1, retryable)
                trace.retry(response.statusCode, null, wait)
                retrySleep(wait)
                attempt += 1
            }
        } catch (error: Throwable) {
            if (error !is CancellationException) trace.failure(error)
            throw error
        } finally {
            trace.end()
        }
    }

    /**
     * The URL and headers one attempt sends, credentials included, as the JDK
     * transport builds them; a custom transport shows the request as handed to it.
     */
    private fun observed(request: Request): Pair<String, Map<String, List<String>>> {
        val sent = (transport as? JdkTransport)?.let { jdk -> try { jdk.prepare(request, options).build() } catch (_: Exception) { null } }
        return if (sent != null) Pair(sent.uri().toString(), sent.headers().map())
        else Pair(request.url, request.headers.mapValues { listOf(it.value) })
    }
