        private fun range(value: Double, bounds: Map<String, Any?>, minimum: String, maximum: String) {
            if (bounds.containsKey(minimum) && value < num(bounds[minimum]) || bounds.containsKey(maximum) && value > num(bounds[maximum])) throw refused("argument constraint mismatch")
        }
        private fun validate(value: Any?, schema: Map<String, Any?>, schemas: Map<String, Any?>, depth: Int = 0) {
            if (depth > 64 || schema.containsKey("unsupported")) throw refused("argument schema is not qualified")
            if (schema.containsKey("ref")) {
                val ref = str(schema["ref"]); val prefix = "#/components/schemas/"
                if (!ref.startsWith(prefix)) throw refused("unresolved schema reference")
                val segment = ref.substring(prefix.length)
                if (segment.isEmpty() || segment.contains('/')) throw refused("invalid schema reference")
                var index = 0
                while (index < segment.length) {
                    if (segment[index++] == '~' && (index >= segment.length || segment[index++] !in "01")) throw refused("invalid schema reference escape")
                }
                val name = segment.replace("~1", "/").replace("~0", "~")
                if (!schemas.containsKey(name)) throw refused("unresolved schema reference")
                validate(value, obj(schemas[name]), schemas, depth + 1)
            }
            if (value == null && flag(schema, "nullable")) return
            for (keyword in listOf("one_of", "any_of", "all_of")) {
                if (!schema.containsKey(keyword)) continue
                val branches = arr(schema[keyword]); var matches = 0
                for (branch in branches) {
                    try { validate(value, obj(branch), schemas, depth + 1); matches++ }
                    catch (_: SessionException) { continue } // Entire graph was qualified before emission.
                }
                if (keyword == "one_of" && matches != 1 || keyword == "any_of" && matches == 0 || keyword == "all_of" && matches != branches.size) throw refused("schema composition mismatch")
            }
            if (schema.containsKey("not")) {
                val matches = try { validate(value, obj(schema["not"]), schemas, depth + 1); true } catch (_: SessionException) { false }
                if (matches) throw refused("excluded schema")
            }
            if (schema.containsKey("const") && !equal(value, schema["const"])) throw refused("const mismatch")
            if (schema.containsKey("enum")) {
                val values = arr(schema["enum"])
                if (values.isNotEmpty() && values.none { equal(value, it) }) throw refused("enum mismatch")
            }
            if (schema.containsKey("type")) {
                val valid = when (str(schema["type"])) {
                    "null" -> value == null
                    "object" -> value is Map<*, *>
                    "array" -> value is List<*>
                    "string" -> value is String
                    "boolean" -> value is Boolean
                    "number" -> value is Number
                    "integer" -> value is Number && Math.rint(num(value)) == num(value)
                    else -> false
                }
                if (!valid) throw refused("argument type mismatch")
            }
            val bounds = obj(schema["constraints"] ?: emptyMap<String, Any?>())
            if (bounds.containsKey("pattern")) throw refused("regex-constrained arguments are not qualified")
            if (value is Number) {
                val n = num(value); range(n, bounds, "minimum", "maximum")
                if (bounds.containsKey("exclusiveMinimum") && n <= num(bounds["exclusiveMinimum"]) || bounds.containsKey("exclusiveMaximum") && n >= num(bounds["exclusiveMaximum"])) throw refused("exclusive numeric bound")
                if (bounds.containsKey("multipleOf")) {
                    val divisor = num(bounds["multipleOf"])
                    if (divisor <= 0 || kotlin.math.abs(n / divisor - Math.rint(n / divisor)) > 1e-9) throw refused("multipleOf mismatch")
                }
            }
            if (value is String) range(value.codePointCount(0, value.length).toDouble(), bounds, "minLength", "maxLength")
            if (value is List<*>) {
                range(value.size.toDouble(), bounds, "minItems", "maxItems"); val unique = mutableSetOf<String>()
                for (item in value) {
                    if (flag(bounds, "uniqueItems") && !unique.add(String(bytes(item), Charsets.UTF_8))) throw refused("duplicate array item")
                    if (schema.containsKey("items")) validate(item, obj(schema["items"]), schemas, depth + 1)
                }
            }
            if (value is Map<*, *>) {
                val fields = obj(value); range(fields.size.toDouble(), bounds, "minProperties", "maxProperties")
                val properties = obj(schema["properties"] ?: emptyMap<String, Any?>())
                for (key in arr(schema["required"] ?: emptyList<String>())) if (!fields.containsKey(str(key))) throw refused("required property missing")
                for ((key, item) in fields) {
                    if (properties.containsKey(key)) validate(item, obj(properties[key]), schemas, depth + 1)
                    else if (schema["additional_properties"] == false) throw refused("unknown object property")
                    else if (schema["additional_properties"] is Map<*, *>) validate(item, obj(schema["additional_properties"]), schemas, depth + 1)
                }
            }
        }
    }

    /** Authenticated local storage; keep the checkpoint and permanent initialization guard together. */
    public class Checkpoint(path: java.nio.file.Path, key: ByteArray) {
        private val path = path.toAbsolutePath().normalize()
        private val key = key.copyOf()
        private var revision = ""
        init { if (key.size < 32) throw refused("external checkpoint key of at least 32 bytes required") }
        private fun sibling(suffix: String): java.nio.file.Path = path.resolveSibling(path.fileName.toString() + suffix)
        private fun mac(value: Any?): ByteArray = javax.crypto.Mac.getInstance("HmacSHA256").run {
            init(javax.crypto.spec.SecretKeySpec(key, "HmacSHA256")); doFinal(bytes(value))
        }
        private fun read(): ByteArray? = try {
            java.nio.channels.FileChannel.open(path, java.nio.file.StandardOpenOption.READ).use { channel ->
                val length = channel.size()
                if (length > 128L * 1024 * 1024) throw refused("checkpoint byte limit")
                val buffer = java.nio.ByteBuffer.allocate(length.toInt())
                while (buffer.hasRemaining()) if (channel.read(buffer) < 0) throw refused("checkpoint changed during read")
                if (channel.read(java.nio.ByteBuffer.allocate(1)) != -1) throw refused("checkpoint changed during read")
                buffer.array()
            }
        } catch (_: java.nio.file.NoSuchFileException) { null }
        @Synchronized internal fun load(): Map<String, Any?>? {
            try {
                val payload = read()
                if (payload == null) {
                    if (java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint missing after initialization")
                    revision = ""; return null
                }
                if (!java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing")
                val envelope = obj(parse(payload))
                if (envelope.keys != setOf("state", "mac")) throw refused("invalid checkpoint envelope")
                val supplied = try { java.util.HexFormat.of().parseHex(str(envelope["mac"])) } catch (error: IllegalArgumentException) { throw refused("checkpoint authentication failed", error) }
                if (!java.security.MessageDigest.isEqual(supplied, mac(envelope["state"]))) throw refused("checkpoint authentication failed")
                revision = hash(payload); return obj(envelope["state"])
            } catch (error: SessionException) { throw error }
            catch (error: Exception) { throw refused("checkpoint load failed", error) }
        }
        @Synchronized internal fun save(state: Map<String, Any?>) {
            try {
                java.nio.file.Files.createDirectories(path.parent)
                val lock = sibling(".lock")
                val writer = java.nio.channels.FileChannel.open(lock, java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE)
                try {
                    writer.use {
                        var temporary: java.nio.file.Path? = null
                        try {
                            val previous = read()
                            if ((previous?.let { hash(it) } ?: "") != revision) throw refused("checkpoint changed by another session")
                            val payload = bytes(mapOf("state" to state, "mac" to hex(mac(state))))
                            if (payload.size > 128 * 1024 * 1024) throw refused("checkpoint byte limit")
                            if (revision.isEmpty()) {
                                java.nio.channels.FileChannel.open(sibling(".started"), java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE).use { guard ->
                                    val data = java.nio.ByteBuffer.wrap(PROTOCOL.toByteArray(Charsets.UTF_8))
                                    while (data.hasRemaining()) guard.write(data)
                                    guard.force(true)
                                }
                            } else if (!java.nio.file.Files.exists(sibling(".started"))) throw refused("checkpoint initialization guard missing")
                            val pending = sibling("." + java.util.UUID.randomUUID() + ".tmp"); temporary = pending
                            java.nio.channels.FileChannel.open(pending, java.nio.file.StandardOpenOption.CREATE_NEW, java.nio.file.StandardOpenOption.WRITE).use { file ->
                                val data = java.nio.ByteBuffer.wrap(payload)
                                while (data.hasRemaining()) file.write(data)
                                file.force(true)
                            }
                            java.nio.file.Files.move(pending, path, java.nio.file.StandardCopyOption.ATOMIC_MOVE, java.nio.file.StandardCopyOption.REPLACE_EXISTING)
                            temporary = null; revision = hash(payload)
                        } finally { temporary?.let { java.nio.file.Files.deleteIfExists(it) } }
                    }
                } finally { java.nio.file.Files.delete(lock) } // Only after this writer acquired the lock.
            } catch (error: java.io.IOException) { throw refused("checkpoint persistence failed", error) }
        }
    }

    private val registry = discovery()
    private val schemas = obj(parse(SCHEMAS_JSON.toByteArray(Charsets.UTF_8)))
    private val limits = options.limits.toMap()
    private val allowed = options.allowedTools.toSet()
    private val running = java.util.concurrent.atomic.AtomicBoolean()
    private var storageFailure: Throwable? = null
    private val state: MutableMap<String, Any?>

    init {
        if (limits.keys != KEYS.toSet() || limits.any { (key, value) -> !value.isFinite() || value <= 0 || count(key) && (Math.rint(value) != value || value > 9007199254740991.0) }) throw refused("all nine positive finite budgets and safe integer counts required")
        if (!digest(options.artifactHash) || provider.version != PROVIDER_PROTOCOL || provider.identity.isEmpty()) throw refused("provider identity and exact archive hash required")
        if (allowed.isEmpty() || allowed.size != options.allowedTools.size || !registry.keys.containsAll(allowed)) throw refused("explicit unique known operation allowlist required")
        val binding = mapOf("version" to PROTOCOL, "language" to "kotlin", "source" to SOURCE,
            "artifact" to options.artifactHash, "registry" to hash(REGISTRY_JSON.toByteArray(Charsets.UTF_8)),
            "provider" to mapOf("identity" to provider.identity, "version" to provider.version), "limits" to limits, "allowed_tools" to allowed.sorted())
